// Совет в карточке приветствия дашборда (#444b9ee7). Меняют только localStorage своего окна браузера.
import { expect, Page } from '@playwright/test';
import { Lang, greetingCard, setLanguage } from './dashboard-helpers';

/** localStorage: techory:dashboard-tip:<userId>:<companyId>:<tipId> = 'dismissed'. */
export const TIP_KEY_PREFIX = 'techory:dashboard-tip:';

export const HIDE_TIP_LABEL: Record<Lang, string> = { en: 'Hide this tip', he: 'הסתר טיפ' };

/** Известные советы EN: текст ссылки → путь. */
export const TIPS = {
  stripe: { text: 'Take card payments', href: /\/StripeSettings/ },
  profile: { text: 'Finish your company profile', href: /\/CompanySettings/ },
  payroll: { text: 'Payroll in Reports', href: /\/reports/i },
  map: { text: 'See your leads on the map', href: /\/Map/ },
  priceBook: { text: 'Fill items in faster', href: /\/PriceBook/ },
};

/** Совет появляется через 3–4.5 с после загрузки страницы. */
export const TIP_DELAY_MAX_MS = 4500;

/**
 * Удалить ключи советов ДО первой загрузки страницы. Один раз на вкладку (флаг в sessionStorage),
 * чтобы reload внутри теста не стирал скрытые советы.
 */
export async function clearTipsBeforeLoad(page: Page) {
  await page.addInitScript((prefix) => {
    try {
      if (window.sessionStorage.getItem('qa-auto-tips-cleared')) return;
      Object.keys(window.localStorage)
        .filter((k) => k.startsWith(prefix))
        .forEach((k) => window.localStorage.removeItem(k));
      window.sessionStorage.setItem('qa-auto-tips-cleared', '1');
    } catch { /* ignore */ }
  }, TIP_KEY_PREFIX);
}

/** Очистка в конце теста: удалить ключи советов (если страница сайта открыта). */
export async function removeTipKeys(page: Page) {
  if (page.isClosed() || !page.url().startsWith('http')) return;
  await page.evaluate((prefix) => {
    Object.keys(window.localStorage)
      .filter((k) => k.startsWith(prefix))
      .forEach((k) => window.localStorage.removeItem(k));
  }, TIP_KEY_PREFIX).catch(() => { /* страница ушла — контекст всё равно одноразовый */ });
}

/** Ключи скрытых советов в localStorage. */
export async function dismissedTipKeys(page: Page): Promise<string[]> {
  return page.evaluate((prefix) =>
    Object.keys(window.localStorage).filter((k) => k.startsWith(prefix) && window.localStorage.getItem(k) === 'dismissed'),
  TIP_KEY_PREFIX);
}

export const hideTipButton = (page: Page, lang: Lang) =>
  greetingCard(page).getByRole('button', { name: HIDE_TIP_LABEL[lang], exact: true });

/** Ссылка совета — ближайший к кнопке X контейнер со ссылкой. */
export const tipLink = (page: Page, lang: Lang) =>
  hideTipButton(page, lang).locator('xpath=ancestor::*[.//a][1]').getByRole('link');

/** Открыть /dashboard (ключи советов предварительно очищены) и дождаться карточки приветствия. */
export async function openDashboardFresh(page: Page, lang: Lang) {
  await setLanguage(page, lang);
  await clearTipsBeforeLoad(page);
  await page.goto('/dashboard');
  await expect(greetingCard(page)).toBeVisible();
}

/** Дождаться совета: появляется через 3–4.5 с — ждём элемент, не таймаут. */
export async function waitForTip(page: Page, lang: Lang) {
  await expect(hideTipButton(page, lang)).toBeVisible({ timeout: 15_000 });
  await expect(hideTipButton(page, lang)).toHaveCount(1);
}

/**
 * Для проверок «совета нет»: дождаться, пока с загрузки страницы пройдёт окно появления совета
 * (условие по часам страницы, а не пауза теста), иначе отсутствие совета ничего не доказывает.
 */
export async function waitTipWindowPassed(page: Page) {
  await page.waitForFunction((ms) => performance.now() > ms, TIP_DELAY_MAX_MS + 1000, { timeout: 15_000 });
}

/** Т1: в карточке приветствия нет «Invoices due». */
export async function expectNoInvoicesDueInCard(page: Page) {
  await expect(greetingCard(page), 'в карточке приветствия не должно быть «Invoices due»').not.toContainText(/Invoices due/i);
}
